class OrdersScreen extends ConsumerWidget{const OrdersScreen({super.key});@override Widget build(BuildContext context,WidgetRef ref){final state=ref.watch(ordersProvider);return Scaffold(appBar:AppBar(title:const Text('طلباتي'),centerTitle:true),body:state.when(loading:()=>const SpikeLoading(),error:(e,_)=>SpikeErrorState(message:e.toString(),onRetry:()=>ref.invalidate(ordersProvider)),data:(orders){if(orders.isEmpty)return const SpikeEmptyState(message:'لا توجد طلبات حتى الآن');return ListView.builder(padding:const EdgeInsets.all(17),itemCount:orders.length,itemBuilder:(context,i){final o=orders[i];return Card(child:ListTile(onTap:()=>context.push('/order/${o.id}'),leading:const CircleAvatar(child:Icon(LucideIcons.shoppingBag,size:20)),title:Text('طلب #${o.id.length>8?o.id.substring(0,8):o.id}',style:const TextStyle(fontWeight:FontWeight.w800)),subtitle:Text('${_status(o.status)} • ${o.paymentMethod=='cod'?'عند الاستلام':'حوالة'}'),trailing:Text('${o.total.toStringAsFixed(2)} ${o.currencyCode}',style:const TextStyle(fontWeight:FontWeight.w900))));});}));}String _status(String s)=>const {'pending_admin_review':'قيد مراجعة الإدارة','approved':'تمت الموافقة','processing':'قيد التجهيز','ready_for_delivery':'جاهز للتوصيل','with_courier':'مع المندوب','delivered':'تم التوصيل','rejected':'مرفوض','returned':'مرتجع'}[s]??s;}
