@override Widget build(BuildContext context){final details=ref.watch(orderDetailsProvider(widget.id)),timeline=ref.watch(orderTimelineProvider(widget.id));return Scaffold(appBar:AppBar(title:const Text('تفاصيل الطلب'),centerTitle:true),body:details.when(loading:()=>const SpikeLoading(),error:(e,_)=>SpikeErrorState(message:e.toString(),onRetry:()=>ref.invalidate(orderDetailsProvider(widget.id))),data:(d){final order=Map<String,dynamic>.from(d['order'] as Map? ?? const {}),subs=(d['suborders'] as List? ?? const []).whereType<Map>().map((e)=>Map<String,dynamic>.from(e)).toList(),items=(d['items'] as List? ?? const []).whereType<Map>().map((e)=>Map<String,dynamic>.from(e)).toList();final transfer=order['payment_method']=='transfer',needsReceipt=transfer&&order['status']=='pending_admin_review'&&(order['receipt_url']==null||'${order['receipt_url']}'.isEmpty);return RefreshIndicator(onRefresh:()async{ref.invalidate(orderDetailsProvider(widget.id));ref.invalidate(orderTimelineProvider(widget.id));await ref.read(orderDetailsProvider(widget.id).future);},child:ListView(padding:const EdgeInsets.all(17),children:[_box(context,Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('الحالة: ${_status('${order['status']??''}')}',style:const TextStyle(fontWeight:FontWeight.w800)),Text('الإجمالي: ${order['total']??0} ${order['currency_code']??''}',style:const TextStyle(fontWeight:FontWeight.w900)),Text('الدفع: ${transfer?'حوالة مالية':'عند الاستلام'} • ${_payment('${order['payment_status']??''}')}'),if(order['address_line']!=null)Text('التوصيل: ${order['address_line']}')])),if(transfer)...[const SizedBox(height:10),_box(context,Column(crossAxisAlignment:CrossAxisAlignment.stretch,children:[const Text('سند الحوالة',style:TextStyle(fontWeight:FontWeight.w800)),const SizedBox(height:5),Text(needsReceipt?'ارفع صورة السند ليتمكن الأدمن من مراجعة الطلب.':'حالة السند: ${_payment('${order['payment_status']??''}')}',style:const TextStyle(fontSize:11)),if(needsReceipt)...[const SizedBox(height:8),FilledButton.icon(style:FilledButton.styleFrom(backgroundColor:spikeRed),onPressed:receiptBusy?null:_receipt,icon:const Icon(LucideIcons.upload,size:18),label:Text(receiptBusy?'جاري الرفع...':'رفع سند الحوالة'))]]))],const SizedBox(height:12),const Text('تتبع الطلب',style:TextStyle(fontSize:18,fontWeight:FontWeight.w800)),const SizedBox(height:8),timeline.when(loading:()=>const Padding(padding:EdgeInsets.all(12),child:SpikeLoading()),error:(e,_)=>Text(e.toString()),data:(rows)=>rows.isEmpty?const Text('لا توجد تحديثات بعد',style:TextStyle(color:Colors.grey)):Column(children:rows.map((x)=>ListTile(contentPadding:EdgeInsets.zero,leading:const CircleAvatar(radius:6,backgroundColor:spikeRed),title:Text(_status('${x['status']??''}'),style:const TextStyle(fontWeight:FontWeight.w700)),subtitle:Text('${x['store_name']??''}${x['created_at']==null?'':' • ${x['created_at']}'}'))).toList())),const SizedBox(height:12),for(final s in subs)_box(context,Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('${s['store_name']??''}',style:const TextStyle(fontWeight:FontWeight.w800)),Text('الحالة: ${_status('${s['status']??''}')}'),if(s['delivery_office_name']!=null)Text('مكتب التوصيل: ${s['delivery_office_name']}'),if(s['shipping_total']!=null)Text('التوصيل: ${s['shipping_total']} ${s['currency_code']??''}')])) ,const SizedBox(height:12),const Text('المنتجات',style:TextStyle(fontSize:18,fontWeight:FontWeight.w800)),for(final item in items)_box(context,Row(children:[Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('${item['product_name']??''}',style:const TextStyle(fontWeight:FontWeight.w700)),Text('${item['store_name']??''} • ${item['variant_title']??''}',style:const TextStyle(fontSize:10,color:Colors.grey))])),Text('×${item['quantity']??1}')]))]));}));}
Widget _box(BuildContext context,Widget child)=>Container(margin:const EdgeInsets.only(bottom:9),padding:const EdgeInsets.all(14),decoration:BoxDecoration(color:Theme.of(context).brightness==Brightness.dark?spikeDarkPanel:spikePanel,borderRadius:BorderRadius.circular(20)),child:child);String _status(String s)=>const {'pending_admin_review':'قيد مراجعة الإدارة','accepted':'مقبول','approved':'تمت الموافقة','processing':'قيد التجهيز','ready_for_delivery':'جاهز للتوصيل','assigned':'تم تعيين مكتب التوصيل','picked_up':'تم استلامه من المتجر','with_courier':'مع المندوب','delivered':'تم التوصيل','rejected':'مرفوض','returned':'مرتجع'}[s]??s;String _payment(String s)=>const {'pending_review':'قيد مراجعة السند','approved':'تم اعتماد الدفع','pending_collection':'يُحصّل عند الاستلام','paid':'مدفوع','rejected':'مرفوض'}[s]??s;}
